//! KEK derivation (Argon2id) and AEAD sealing (plan.md §6.1).
//!
//! This layer only turns a password into a KEK and bytes into ciphertext; it touches no files or network (I2 gate).
//! The on-disk keystore format is defined by `sme-client-store`.

use argon2::{Algorithm, Argon2, Params, Version};
use chacha20poly1305::aead::{Aead, KeyInit, Payload};
use chacha20poly1305::{ChaCha20Poly1305, Nonce};
use zeroize::Zeroizing;

/// Password salt length (docs/INFRA.md §3: generated by the client).
pub const SALT_LEN: usize = 16;

/// KEK length.
pub const KEY_LEN: usize = 32;

/// AEAD nonce length; [`seal`] prepends it to the ciphertext.
pub const NONCE_LEN: usize = 12;

/// Argon2id parameters. Defaults to OWASP's first recommendation (19 MiB / t=2 / p=1),
/// A single derivation takes tens of milliseconds, fine for mobile. Parameters are stored with the keystore and can be upgraded later.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct KdfParams {
    /// Memory cost in KiB.
    pub m_cost: u32,
    /// Iterations.
    pub t_cost: u32,
    /// Parallelism.
    pub p_cost: u32,
}

impl Default for KdfParams {
    fn default() -> Self {
        Self {
            m_cost: 19_456,
            t_cost: 2,
            p_cost: 1,
        }
    }
}

#[derive(Debug)]
pub enum CryptoError {
    InvalidKdfParams,
    KdfFailure(argon2::Error),
    RandomSource,
    SealFailure,
    OpenFailure,
}

impl std::fmt::Display for CryptoError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidKdfParams => write!(f, "invalid Argon2id parameters"),
            Self::KdfFailure(error) => write!(f, "Argon2id key derivation failed: {error}"),
            Self::RandomSource => write!(f, "OS random source unavailable"),
            Self::SealFailure => write!(f, "AEAD sealing failed"),
            Self::OpenFailure => {
                write!(
                    f,
                    "AEAD authentication failed (wrong password or tampered data)"
                )
            }
        }
    }
}

impl std::error::Error for CryptoError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::KdfFailure(error) => Some(error),
            _ => None,
        }
    }
}

/// Generate a random salt.
pub fn random_salt() -> Result<[u8; SALT_LEN], CryptoError> {
    let mut salt = [0u8; SALT_LEN];
    getrandom::fill(&mut salt).map_err(|_| CryptoError::RandomSource)?;
    Ok(salt)
}

/// `Argon2id(password, salt, params)` -> KEK. The KEK lives in memory only and is wiped by [`Zeroizing`].
pub fn derive_kek(
    password: &[u8],
    salt: &[u8; SALT_LEN],
    params: &KdfParams,
) -> Result<Zeroizing<[u8; KEY_LEN]>, CryptoError> {
    let params = Params::new(params.m_cost, params.t_cost, params.p_cost, Some(KEY_LEN))
        .map_err(|_| CryptoError::InvalidKdfParams)?;
    let argon2 = Argon2::new(Algorithm::Argon2id, Version::V0x13, params);

    let mut kek = Zeroizing::new([0u8; KEY_LEN]);
    argon2
        .hash_password_into(password, salt, &mut kek[..])
        .map_err(CryptoError::KdfFailure)?;
    Ok(kek)
}

/// Encrypt and return `nonce || ciphertext+tag`. `aad` is authenticated but not encrypted.
pub fn seal(kek: &[u8; KEY_LEN], aad: &[u8], plaintext: &[u8]) -> Result<Vec<u8>, CryptoError> {
    let cipher = ChaCha20Poly1305::new(kek.into());

    let mut nonce_bytes = [0u8; NONCE_LEN];
    getrandom::fill(&mut nonce_bytes).map_err(|_| CryptoError::RandomSource)?;

    let ciphertext = cipher
        .encrypt(
            Nonce::from_slice(&nonce_bytes),
            Payload {
                msg: plaintext,
                aad,
            },
        )
        .map_err(|_| CryptoError::SealFailure)?;

    let mut sealed = Vec::with_capacity(NONCE_LEN + ciphertext.len());
    sealed.extend_from_slice(&nonce_bytes);
    sealed.extend_from_slice(&ciphertext);
    Ok(sealed)
}

/// Open the output of [`seal`]; authentication failure (wrong password or tampered data) returns [`CryptoError::OpenFailure`].
pub fn open(
    kek: &[u8; KEY_LEN],
    aad: &[u8],
    sealed: &[u8],
) -> Result<Zeroizing<Vec<u8>>, CryptoError> {
    if sealed.len() < NONCE_LEN {
        return Err(CryptoError::OpenFailure);
    }
    let (nonce_bytes, ciphertext) = sealed.split_at(NONCE_LEN);
    let cipher = ChaCha20Poly1305::new(kek.into());

    let plaintext = cipher
        .decrypt(
            Nonce::from_slice(nonce_bytes),
            Payload {
                msg: ciphertext,
                aad,
            },
        )
        .map_err(|_| CryptoError::OpenFailure)?;
    Ok(Zeroizing::new(plaintext))
}
